begin;
-- Historical signature completion is independent of later deal/link lifecycle.
-- Access eligibility remains in uploaded_pdf_current and every existing RPC.
create or replace function private.uploaded_pdf_json(s private.uploaded_pdf_sources) returns jsonb language sql security invoker set search_path='' as $$select jsonb_build_object('id',s.id,'companyId',s.company_id,'dealId',s.deal_id,'customerId',s.customer_id,'companyName',s.company_name,'recipientName',s.recipient_name,'recipientEmail',s.recipient_email,'filename',s.filename,'originalSha256',s.original_sha256,'byteSize',s.byte_size,'pageCount',s.page_count,'objectPath',s.object_path,'documentHash',s.document_hash,'canonicalContent',s.canonical_content,'createdAt',s.created_at,'expiresAt',s.expires_at,'linkRevoked',exists(select 1 from private.uploaded_pdf_cancellations where source_id=s.id),'status',case when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='company'and document_hash=s.document_hash)and exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer'and document_hash=s.document_hash)then 'completed' when not private.uploaded_pdf_current(s) or(s.expires_at<=clock_timestamp() and not exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer')) then 'unavailable' when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='company') then 'pending' else 'draft' end,'companySignature',(select jsonb_build_object('actorId',actor_user_id,'fullName',full_name,'signedAt',signed_at,'documentHash',document_hash,'consentVersion',consent_version) from private.uploaded_pdf_signatures where source_id=s.id and party='company'),'customerSignature',(select jsonb_build_object('actorId',actor_user_id,'fullName',full_name,'signedAt',signed_at,'documentHash',document_hash,'consentVersion',consent_version) from private.uploaded_pdf_signatures where source_id=s.id and party='customer'),'delivery',(select status from private.uploaded_pdf_emails where source_id=s.id and kind=case when exists(select 1 from private.uploaded_pdf_signatures where source_id=s.id and party='customer') then 'completed' else 'invitation' end),'archive',(select jsonb_build_object('pdfPath',pdf_path,'pdfSha256',pdf_sha256,'evidencePath',evidence_path,'evidenceSha256',evidence_sha256) from private.uploaded_pdf_artifacts where source_id=s.id))$$;
commit;
